function teamHome(r,own=true){if(!r)return'<div class="empty">No roster found for this user.</div>';const opt=optimal(r),starts=(r.starters||[]).filter(x=>x&&x!=='0'),set=new Set(starts),bench=(r.players||[]).filter(x=>!set.has(x));return`<div class="toolbar"><div><div class="eyebrow">${own?'Your team':'Team view'}</div><h1 class="page-title">${esc(tname(r.roster_id))}</h1></div><div style="margin-left:auto">${weekSel()}</div></div>${matchup(r)}<div class="section-head"><h2>Starters</h2><span class="muted small">Model lineup indicators use league roster slots</span></div>${rosterTable(r,starts,opt)}<div class="section-head"><h2>Bench</h2></div>${rosterTable(r,bench,opt)}<div class="section-head"><h2>Draft Picks</h2></div>${picks(r)}`}
function teams(){const r=rby(st.team)||st.rosters[0];return`<div class="toolbar"><select class="select" data-a="team">${st.rosters.map(x=>`<option value="${x.roster_id}" ${x.roster_id===r?.roster_id?'selected':''}>${esc(tname(x.roster_id))}</option>`).join('')}</select></div>${teamHome(r,false)}`}
function leagueOverview(){const ranks=[...st.rosters].sort((a,b)=>(ppg(b)||0)*10+rdyn(b)/100+(rproj(b)||0)*3-((ppg(a)||0)*10+rdyn(a)/100+(rproj(a)||0)*3)),stand=[...st.rosters].sort((a,b)=>n(b.settings?.wins,0)-n(a.settings?.wins,0)||((n(b.settings?.fpts,0)+n(b.settings?.fpts_decimal,0)/100)-(n(a.settings?.fpts,0)+n(a.settings?.fpts_decimal,0)/100))),po=+(st.league?.settings?.playoff_teams||6);return`<div class="toolbar"><div><div class="eyebrow">League overview</div><h1 class="page-title">${esc(st.league.name)}</h1></div><div style="margin-left:auto">${weekSel()}</div></div><div class="table-wrap"><table><thead><tr><th>Rank</th><th>Team</th><th>Window</th><th>Dynasty Value</th><th>Week Projection</th><th>Avg PPG</th><th>Avg. Age</th><th>Biggest Need</th></tr></thead><tbody>${ranks.map((r,i)=>`<tr><td><strong>#${i+1}</strong></td><td style="text-align:left"><strong>${esc(tname(r.roster_id))}</strong></td><td>${windowOf(r)}</td><td>${fi(rdyn(r))}</td><td>${f(rproj(r))}</td><td>${f(ppg(r))}</td><td>${f(avgAge(r))}</td><td><span class="pill warn">${need(r)}</span></td></tr>`).join('')}</tbody></table></div><div class="section-head"><h2>Current Playoff Picture</h2><span class="muted small">${po} playoff spots</span></div>${stand.map((r,i)=>{const s=r.settings||{},pts=n(s.fpts,0)+n(s.fpts_decimal,0)/100,status=i<po?'In playoff position':i===po?'On the bubble':'Outside looking in';return`<div class="standing-row"><strong>#${i+1}</strong><div><strong>${esc(tname(r.roster_id))}</strong><div class="muted small">${n(s.wins,0)}-${n(s.losses,0)}</div></div><strong>${f(pts)}</strong><span class="muted small">Points for</span><span class="pill ${i<po?'good':i===po?'warn':''}">${status}</span></div>`}).join('')}`}
function aval(k){if(k.startsWith('player:'))return dval(k.slice(7));const[,y,r,o]=k.split(':');return pickVal({season:+y,round:+r,original:+o})}function total(s){return[...s].reduce((a,k)=>a+aval(k),0)}
function assets(r,set,side){const ps=(r?.players||[]).filter(id=>!isDstId(id,st.players?.[id])).map(id=>({k:`player:${id}`,l:pname(id),m:st.players?.[id]?.position||'',v:dval(id)})),pk=pickAssets(r?.roster_id).map(x=>{const o=pickMeta(x);return{k:x.key,l:`${x.season} ${ord(x.round)} · ${o.proj}`,m:`${x.original===r.roster_id?'Own pick':`via ${tname(x.original)}`} · current ${o.cur} · ${o.detail}`,v:pickVal(x)}});return`<div class="asset-list">${[...ps,...pk].map(a=>`<button class="asset ${set.has(a.k)?'selected':''}" data-side="${side}" data-asset="${esc(a.k)}"><span style="text-align:left"><strong>${esc(a.l)}</strong><span class="muted small" style="display:block">${esc(a.m)}</span></span><strong>${fi(a.v)}</strong></button>`).join('')}</div>`}
function recommendation(){const r=me();if(!r)return'';const nd=need(r),mine=(r.players||[]).map(id=>({id,v:dval(id),p:st.players?.[id]})).filter(x=>x.v>0);let best;for(const o of st.rosters.filter(x=>x.roster_id!==r.roster_id))for(const id of o.players||[]){const p=st.players?.[id],v=dval(id);if(p?.position!==nd||!v)continue;const g=mine.filter(x=>x.p?.position!==nd).sort((a,b)=>Math.abs(a.v-v)-Math.abs(b.v-v))[0];if(g&&(!best||Math.abs(g.v-v)<best.d))best={o,id,v,g,d:Math.abs(g.v-v)}}return best?`<div class="recommendation"><div class="rec-rank">TOP TRADE PATH</div><div class="rec-title">Target ${esc(pname(best.id))} from ${esc(tname(best.o.roster_id))}</div><p class="muted">Your largest modeled need is ${nd}. A value-balanced starting point is ${esc(pname(best.g.id))}; refine with draft capital in the simulator.</p><div class="grid grid-3"><div class="metric"><div class="metric-label">You send</div><div class="metric-value">${fi(best.g.v)}</div></div><div class="metric"><div class="metric-label">You receive</div><div class="metric-value">${fi(best.v)}</div></div><div class="metric"><div class="metric-label">Raw gap</div><div class="metric-value">${fi(best.g.v-best.v)}</div></div></div></div>`:`<div class="recommendation"><div class="rec-title">Improve ${nd}</div><p class="muted">No clean one-for-one target surfaced. Build a package below.</p></div>`}
function trade(){const a=rby(st.tradeA)||me()||st.rosters[0],b=rby(st.tradeB)||st.rosters.find(x=>x.roster_id!==a?.roster_id),ta=total(st.assetsA),tb=total(st.assetsB),gap=ta-tb,d=Math.abs(gap)/Math.max(ta,tb,1),bal=d<=.05?'Near even':d<=.15?'Moderate gap':'Large gap';const opts=r=>st.rosters.map(x=>`<option value="${x.roster_id}" ${x.roster_id===r?.roster_id?'selected':''}>${esc(tname(x.roster_id))}</option>`).join('');return`<div class="eyebrow">Trade Center</div><h1 class="page-title">Recommended trades + simulator</h1><p class="page-subtitle">Compare dynasty value, draft capital and roster fit. Balance is not an acceptance probability.</p><div class="section-head"><h2>Recommended</h2></div>${recommendation()}<div class="section-head"><h2>Trade Simulator</h2><span class="pill ${d<=.05?'good':d<=.15?'warn':'bad'}">${bal}</span></div><div class="trade-layout"><div class="card card-pad"><select class="select" data-a="tradeA">${opts(a)}</select><div style="height:12px"></div>${assets(a,st.assetsA,'a')}<div class="trade-total"><span>Total value</span><span>${fi(ta)}</span></div></div><div class="card card-pad"><select class="select" data-a="tradeB">${opts(b)}</select><div style="height:12px"></div>${assets(b,st.assetsB,'b')}<div class="trade-total"><span>Total value</span><span>${fi(tb)}</span></div></div></div><div class="grid grid-4" style="margin-top:14px"><div class="metric"><div class="metric-label">Value difference</div><div class="metric-value">${fi(gap)}</div></div><div class="metric"><div class="metric-label">Balance</div><div class="metric-value" style="font-size:18px">${bal}</div></div><div class="metric"><div class="metric-label">${esc(tname(a?.roster_id))} need</div><div class="metric-value">${need(a)}</div></div><div class="metric"><div class="metric-label">${esc(tname(b?.roster_id))} need</div><div class="metric-value">${need(b)}</div></div></div><p class="muted small">Pick values start from the model's round/year baseline, then adjust for the original team's projected draft slot. Current standings gain weight as the season progresses; farther-out picks regress toward the middle because their exact slot is less certain.</p>`}
function moves(){const r=me();if(!r)return'<div class="empty">Connect a roster first.</div>';const nd=need(r),opt=optimal(r),cur=new Set(r.starters||[]),swap=[...opt.entries()].find(([id])=>!cur.has(id)),sur=['QB','RB','WR','TE'].map(p=>({p,c:(r.players||[]).filter(id=>st.players?.[id]?.position===p).length})).sort((a,b)=>b.c-a.c)[0],recs=[[`Upgrade ${nd}`,`${nd} is your largest relative roster need.`,`Open Trade Center and target teams strong at ${nd}.`],...(swap?[[`Start ${pname(swap[0])}`,`The optimizer places this player in ${swap[1]}.`,'Review the Home tab before kickoff.']]:[]),[`Shop surplus ${sur?.p||'depth'}`,`You carry ${sur?.c||0} ${sur?.p||''} assets, your deepest raw position group.`,'Use depth to address need before spending premium picks.']];return`<div class="eyebrow">Recommended Moves</div><h1 class="page-title">What should you do next?</h1><p class="page-subtitle">Prioritized GM actions from your roster, league context, projections and dynasty values.</p><div class="grid">${recs.map((x,i)=>`<div class="recommendation"><div class="rec-rank">#${i+1}</div><div class="rec-title">${esc(x[0])}</div><p class="muted">${esc(x[1])}</p><strong>Best path</strong><p>${esc(x[2])}</p></div>`).join('')}</div>`}
function leagueShell(){let x=st.loading?'<div class="empty">Loading league…</div>':st.tab==='home'?teamHome(me()):st.tab==='teams'?teams():st.tab==='league'?leagueOverview():st.tab==='trade'?trade():moves();return layout(st.league.name,tabs()+x)}
const ESPN_SUMMARY='https://site.api.espn.com/apis/site/v2/sports/football/nfl/summary';
async function loadGameDetails(id,force=false){const key=String(id);if(!force&&st.gameDetails.has(key)&&!st.gameDetails.get(key)?.error)return st.gameDetails.get(key);st.gameDetails.set(key,{loading:true});render();const data=await liveJson(`${ESPN_SUMMARY}?event=${encodeURIComponent(key)}`,null),value=data||{error:true};st.gameDetails.set(key,value);render();return value}
async function liveLoad(){const ns=await nflState(),data=await liveJson(`${ESPN}?dates=${ns?.season||st.season}&seasontype=2&week=${st.week}`,{});st.games=data?.events||[];const ids=new Set(st.games.map(e=>String(e.id)));for(const id of [...st.gameOpen])if(!ids.has(id))st.gameOpen.delete(id);render();const open=[...st.gameOpen];if(open.length)await Promise.all(open.map(id=>loadGameDetails(id,true)))}
function gameTeamLogo(x){return x?.team?.logo||x?.team?.logos?.[0]?.href||''}
function periodScore(x){const q=Array.isArray(x?.linescores)?x.linescores:[];return q.map((z,i)=>`<span><small>${i<4?`Q${i+1}`:`OT${i-3}`}</small><strong>${esc(z?.displayValue??z?.value??'—')}</strong></span>`).join('')}
function teamStatIndex(teamBox){const m=new Map;for(const x of teamBox?.statistics||[]){m.set(String(x?.name||'').toLowerCase(),x);m.set(normName(x?.label||x?.displayName||''),x)}return m}
function teamStatValue(teamBox,names){const m=teamStatIndex(teamBox);for(const k of names){const x=m.get(String(k).toLowerCase())||m.get(normName(k));if(x)return x.displayValue??x.value??'—'}return'—'}
function gameTeamStats(box,a,h){const teams=box?.teams||[],find=x=>teams.find(t=>String(t?.team?.id)===String(x?.team?.id))||teams.find(t=>String(t?.team?.abbreviation||'').toUpperCase()===String(x?.team?.abbreviation||'').toUpperCase()),ab=find(a),hb=find(h),rows=[['First downs',['firstDowns','1st Downs']],['Total yards',['totalYards','Total Yards']],['Passing yards',['netPassingYards','passingYards','Passing Yards']],['Rushing yards',['rushingYards','Rushing Yards']],['Third down',['thirdDownEff','3rd Down Efficiency']],['Turnovers',['turnovers','Turnovers']],['Penalties',['totalPenaltiesYards','Penalties']],['Possession',['possessionTime','Possession Time']]];if(!ab&&!hb)return'';return`<div class="game-section"><div class="game-section-title">Team stats</div><div class="game-team-stats"><div class="game-stat-head"><span>${esc(a?.team?.abbreviation||'Away')}</span><span>STAT</span><span>${esc(h?.team?.abbreviation||'Home')}</span></div>${rows.map(([label,keys])=>`<div class="game-stat-row"><strong>${esc(teamStatValue(ab,keys))}</strong><span>${esc(label)}</span><strong>${esc(teamStatValue(hb,keys))}</strong></div>`).join('')}</div></div>`}
function boxPlayerCategories(box,competitor){const teamId=String(competitor?.team?.id||''),abbr=String(competitor?.team?.abbreviation||''),entry=(box?.players||[]).find(x=>String(x?.team?.id||'')===teamId)||(box?.players||[]).find(x=>String(x?.team?.abbreviation||'').toUpperCase()===abbr.toUpperCase());if(!entry)return'';const wanted=new Set(['passing','rushing','receiving']),cats=(entry.statistics||[]).filter(g=>wanted.has(String(g?.name||'').toLowerCase())||wanted.has(String(g?.displayName||'').toLowerCase()));if(!cats.length)return'';return`<div class="game-team-box"><div class="game-team-box-title">${gameTeamLogo(competitor)?`<img src="${gameTeamLogo(competitor)}" alt="">`:''}<strong>${esc(competitor?.team?.displayName||abbr)}</strong></div>${cats.map(g=>{const labels=g.labels||g.keys||[],ath=g.athletes||[];if(!ath.length)return'';return`<div class="box-category"><div class="box-category-title">${esc(g.displayName||g.name||'Stats')}</div><div class="box-table-wrap"><table class="box-table"><thead><tr><th>Player</th>${labels.map(x=>`<th>${esc(x)}</th>`).join('')}</tr></thead><tbody>${ath.map(x=>`<tr><td>${esc(x?.athlete?.shortName||x?.athlete?.displayName||'Player')}</td>${(x?.stats||[]).map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div></div>`}).join('')}</div>`}
function gameBox(e,a,h){const key=String(e.id),d=st.gameDetails.get(key);if(!st.gameOpen.has(key))return'';if(!d||d.loading)return'<div class="game-box-loading">Loading box score…</div>';if(d.error)return'<div class="game-box-loading">Box score is temporarily unavailable.</div>';const box=d.boxscore||{};return`<div class="game-box">${gameTeamStats(box,a,h)}<div class="game-player-boxes">${boxPlayerCategories(box,a)}${boxPlayerCategories(box,h)}</div></div>`}
function live(){const cards=st.games.map(e=>{const c=e.competitions?.[0]||{},ts=c.competitors||[],a=ts.find(x=>x.homeAway==='away')||{},h=ts.find(x=>x.homeAway==='home')||{},key=String(e.id),open=st.gameOpen.has(key),status=e.status?.type?.shortDetail||c.status?.type?.shortDetail||'Scheduled';return`<div class="card game-card ${open?'game-open':''}"><div class="game-status-row"><div class="game-status">${esc(status)}</div><div class="muted small">${esc(c.venue?.fullName||'')}</div></div><div class="game-score-team"><div>${gameTeamLogo(a)?`<img src="${gameTeamLogo(a)}" alt="">`:''}<span><strong>${esc(a.team?.abbreviation||'Away')}</strong><small>${esc(a.team?.displayName||'')}</small></span></div><strong>${esc(a.score||'0')}</strong></div><div class="game-score-team"><div>${gameTeamLogo(h)?`<img src="${gameTeamLogo(h)}" alt="">`:''}<span><strong>${esc(h.team?.abbreviation||'Home')}</strong><small>${esc(h.team?.displayName||'')}</small></span></div><strong>${esc(h.score||'0')}</strong></div>${(a.linescores?.length||h.linescores?.length)?`<div class="period-score"><div></div><div class="period-score-row">${periodScore(a)}</div><div class="period-score-row">${periodScore(h)}</div></div>`:''}<button class="game-box-toggle" data-game-toggle="${esc(key)}">${open?'Hide box score':'View box score'} <span>${open?'⌃':'⌄'}</span></button>${gameBox(e,a,h)}</div>`}).join('');return layout('Live NFL Stats',`<div class="toolbar"><div><h1 class="page-title">Live NFL Stats</h1><p class="page-subtitle">Live scores, team box stats and passing/rushing/receiving lines. Expand any game for the full fantasy-relevant box score.</p></div><div style="margin-left:auto">${weekSel()}</div><button class="btn" data-a="refreshLive">Refresh</button></div>${cards?`<div class="scoreboard">${cards}</div>`:'<div class="empty">Loading current NFL games…</div>'}`)}
function leader(title,keys){const a=[...st.seasonStats.entries()].map(([id,row])=>{const p=st.players?.[id]||{},x=dstStats(row),v=maybeNum(field(x,keys));return{id,p,v,name:p.full_name||[p.first_name,p.last_name].filter(Boolean).join(' ')||`Player ${id}`}}).filter(x=>x.v!=null&&x.v>0&&x.name&&['QB','RB','WR','TE'].includes(String(x.p?.position||'').toUpperCase())).sort((a,b)=>b.v-a.v).slice(0,10);return`<div class="card card-pad"><div class="eyebrow">${st.season} NFL season</div><h3>${esc(title)}</h3>${a.length?a.map((x,i)=>`<div class="leader-row leader-open" data-player="${esc(x.id)}" role="button" tabindex="0"><strong>${i+1}</strong><div class="leader-player"><img src="${head(x.id)}" alt="" onerror="this.style.display='none'"><span><strong>${esc(x.name)}</strong><small>${esc(x.p.position||'')} · ${esc(x.p.team||'FA')}</small></span></div><strong>${fi(x.v)}</strong></div>`).join(''):'<div class="empty">Season stats are loading or unavailable.</div>'}</div>`}
function leaders(){const c=[['Passing Yards',['pass_yd','pass_yds','passing_yards','pass_yards']],['Passing TDs',['pass_td','passing_tds','pass_tds']],['Rushing Yards',['rush_yd','rush_yds','rushing_yards','rush_yards']],['Rushing TDs',['rush_td','rushing_tds','rush_tds']],['Receiving Yards',['rec_yd','rec_yds','receiving_yards','rec_yards']],['Receptions',['rec','receptions']],['Receiving TDs',['rec_td','receiving_tds','rec_tds']],['Targets',['rec_tgt','targets']]];return layout('NFL Leaders',`<div class="toolbar"><div><h1 class="page-title">NFL Leaders</h1><p class="page-subtitle">Current ${st.season} regular-season league leaders from live Sleeper season totals.</p></div><button class="btn" data-a="refreshLeaders">Refresh leaders</button></div>${st.seasonStats.size?`<div class="leaders-grid">${c.map(x=>leader(x[0],x[1])).join('')}</div>`:'<div class="empty">Loading current-season NFL statistics…</div>'}`)}
function startsit(){const c=st.compare.map(id=>{const p=st.players?.[id]||{},m=model(id,p);return`<div class="metric"><div class="player-name">${esc(pname(id))}</div><div class="player-meta">${esc(p.position||'')} · ${esc(p.team||'FA')}</div><div class="metric-value">${f(m.projection)}</div><div class="muted small">Floor ${f(m.floor)} · ceiling ${f(m.ceiling)}</div><button class="btn btn-ghost" data-remove="${id}">Remove</button></div>`}).join('');return layout('Start/Sit Tool',`<h1 class="page-title">Start/Sit Tool</h1><p class="page-subtitle">Compare 2–4 players. League-specific recommended lineups live in Dashboard.</p><div class="card card-pad"><input id="search" class="input" placeholder="Search player…"><div id="results" class="asset-list" style="margin-top:9px"></div></div><div class="grid grid-4" style="margin-top:14px">${c||'<div class="empty">Add players to compare.</div>'}</div>`)}
function about(){const m=st.snapshot?.metadata||st.snapshot?.meta||{},v=m.version||m.model_version||st.snapshot?.version||'Production snapshot';return layout('About',`<h1 class="page-title">About Fantasy Model</h1><p class="page-subtitle">Fantasy Model combines weekly projections, uncertainty ranges, dynasty valuation, roster context and league-aware decision tools. Technical model details live here instead of normal fantasy pages.</p><div class="grid grid-3"><div class="metric"><div class="metric-label">Production</div><div class="metric-value" style="font-size:18px">${esc(v)}</div></div><div class="metric"><div class="metric-label">Model rows detected</div><div class="metric-value">${fi(st.rows.length)}</div></div><div class="metric"><div class="metric-label">League integration</div><div class="metric-value" style="font-size:18px">Sleeper</div></div></div>`)}
function render(){const html=st.route==='dashboard'?dashboard():st.route==='live'?live():st.route==='leaders'?leaders():st.route==='startsit'?startsit():about();$('#app').innerHTML=html;bind()}
function bind(){$$('[data-player]').forEach(x=>{x.onclick=()=>openPlayerProfile(x.dataset.player,x.dataset.roster||null);x.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();openPlayerProfile(x.dataset.player,x.dataset.roster||null)}}});$('[data-a="closeProfile"]')?.addEventListener('click',()=>{st.profile=null;st.profileRoster=null;render()});$('[data-profile-backdrop]')?.addEventListener('click',e=>{if(e.target===e.currentTarget){st.profile=null;st.profileRoster=null;render()}});$$('[data-route]').forEach(x=>x.onclick=async()=>{st.route=x.dataset.route;localStorage.fm_route=st.route;render();if(st.route==='live'&&!st.games.length)liveLoad();if(st.route==='leaders'){await Promise.all([players(),loadSeasonStats()]);render()}if(st.route==='startsit')players()});$('[data-a="nav"]')?.addEventListener('click',()=>{st.nav=!st.nav;render()});$('[data-a="load"]')?.addEventListener('click',()=>loadLeagues($('#username').value.trim(),+$('#season').value));$$('[data-league]').forEach(x=>x.onclick=()=>openLeague(x.dataset.league));$('[data-a="refreshLeague"]')?.addEventListener('click',()=>refreshLeague(true));$('[data-a="back"]')?.addEventListener('click',()=>{st.league=null;localStorage.removeItem('fm_league_id');render()});$$('[data-tab]').forEach(x=>x.onclick=()=>{st.tab=x.dataset.tab;localStorage.fm_league_tab=st.tab;render()});$('[data-a="week"]')?.addEventListener('change',async e=>{await setWeek(+e.target.value);if(st.route==='live')liveLoad();if(st.route==='leaders'){await Promise.all([players(),loadSeasonStats()]);render()}});$('[data-a="team"]')?.addEventListener('change',e=>{st.team=+e.target.value;render()});$('[data-a="tradeA"]')?.addEventListener('change',e=>{st.tradeA=+e.target.value;st.assetsA=new Set;render()});$('[data-a="tradeB"]')?.addEventListener('change',e=>{st.tradeB=+e.target.value;st.assetsB=new Set;render()});$$('[data-side]').forEach(x=>x.onclick=()=>{const set=x.dataset.side==='a'?st.assetsA:st.assetsB;set.has(x.dataset.asset)?set.delete(x.dataset.asset):set.add(x.dataset.asset);render()});$('[data-a="refreshLive"]')?.addEventListener('click',liveLoad);$('[data-a="refreshLeaders"]')?.addEventListener('click',async()=>{await Promise.all([players(true),loadSeasonStats(true)]);render();toast('NFL season leaders refreshed.')});$$(`[data-game-toggle]`).forEach(x=>x.onclick=async()=>{const id=String(x.dataset.gameToggle);if(st.gameOpen.has(id)){st.gameOpen.delete(id);render();return}st.gameOpen.add(id);render();await loadGameDetails(id,true)});const search=$('#search');if(search)search.oninput=()=>{const q=search.value.toLowerCase().trim(),found=!q||!st.players?[]:Object.entries(st.players).filter(([,p])=>String(p.full_name||'').toLowerCase().includes(q)&&['QB','RB','WR','TE'].includes(p.position)).slice(0,12),box=$('#results');box.innerHTML=found.map(([id,p])=>`<button class="asset" data-add="${id}"><span><strong>${esc(p.full_name)}</strong><span class="muted small" style="display:block">${esc(p.position)} · ${esc(p.team||'FA')}</span></span><span>+</span></button>`).join('');$$('[data-add]',box).forEach(x=>x.onclick=()=>{if(st.compare.length>=4)return toast('Compare up to four players.');if(!st.compare.includes(x.dataset.add))st.compare.push(x.dataset.add);render()})};$$('[data-remove]').forEach(x=>x.onclick=()=>{st.compare=st.compare.filter(id=>id!==x.dataset.remove);render()})}
async function init(){await Promise.all([snapshot(),nflState()]);render();if(st.username){await loadLeagues(st.username,st.season);const id=localStorage.fm_league_id;if(id&&st.leagues.some(l=>String(l.league_id)===id))await openLeague(id)}if(st.route==='live')liveLoad()}
init();
